import { useUser } from "@stackframe/stack";

export function UserProfile() {
  const user = useUser({ or: "redirect" });

  return (
    <div>
      <h1>Welcome, {user.displayName}</h1>
      <p>Email: {user.primaryEmail}</p>
      <button onClick={() => user.signOut()}>Sign Out</button>
