        recommendations: [
          'Reduce JavaScript execution time',
          'Break up long tasks',
          'Use web workers for heavy computations',
          'Remove unused JavaScript'
        ]
      });
    }

    // CLS recommendations
    if (vitals.cls && vitals.cls.value > 0.1) {
      recommendations.push({
        metric: 'CLS',
        issue: 'High Cumulative Layout Shift',
        recommendations: [
